   973→void UWjWorldPlacementComponent::BindInputActions()
   974→{
   975→	APlayerController* PC = GetPlayerController();
   976→	if (!PC)
   977→	{
   978→		return;
   979→	}
   980→
   981→	// MappingContext 추가
