   998→		{
   999→			EIC->BindAction(CancelAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnCancelAction);
  1000→		}
  1001→		if (RotateAction)
  1002→		{
  1003→			EIC->BindAction(RotateAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnRotateAction);
  1004→		}
  1005→		if (DeleteAction)
  1006→		{
  1007→			EIC->BindAction(DeleteAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnDeleteAction);
  1008→		}
  1009→		if (ScrollAction)
  1010→		{
  1011→			EIC->BindAction(ScrollAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnScrollAction);
  1012→		}
  1013→		if (ToggleAirModeAction)
  1014→		{
