    20→
    21→UWjWorldPlacementComponent::UWjWorldPlacementComponent()
    22→{
    23→	PrimaryComponentTick.bCanEverTick = true;
    24→	PrimaryComponentTick.bStartWithTickEnabled = false;
    25→}
    26→
    27→void UWjWorldPlacementComponent::EnterPlacementMode()
    28→{
    29→	// 기본 컨텍스트: Lobby
    30→	EnterPlacementModeWithContext(EPlacementContext::Lobby);
    31→}
    32→
    33→void UWjWorldPlacementComponent::EnterPlacementModeWithContext(EPlacementContext Context)
    34→{
    35→	if (CurrentMode != EPlacementMode::None)
    36→	{
    37→		return;
    38→	}
    39→
    40→	CurrentContext = Context;
    41→
    42→	// DeveloperSettings에서 입력 설정 및 Catalog 로드 (컨텍스트별)
    43→	LoadInputSettings();
    44→	EnsureCatalogLoaded();
    45→
    46→	CurrentMode = EPlacementMode::Placing;
    47→	SetComponentTickEnabled(true);
    48→	BindInputActions();
    49→
    50→	OnPlacementModeChanged.Broadcast(CurrentMode);
    51→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Entered placement mode (Context: %s)"),
    52→		*GetPlacementContextName(CurrentContext));
    53→}
    54→
    55→void UWjWorldPlacementComponent::ExitPlacementMode()
    56→{
    57→	if (CurrentMode == EPlacementMode::None)
    58→	{
    59→		return;
    60→	}
    61→
    62→	// 호버 하이라이트 해제
    63→	if (HoveredObject)
    64→	{
    65→		HoveredObject->SetHighlighted(false);
    66→		HoveredObject = nullptr;
    67→	}
    68→
    69→	DestroyPreview();
    70→	UnbindInputActions();
    71→	SetComponentTickEnabled(false);
    72→
    73→	SelectedObjectId = NAME_None;
    74→	CurrentMode = EPlacementMode::None;
    75→	bAirPlacementMode = false;
    76→	AirPlaneHeight = 0.f;
    77→	// 컨텍스트는 리셋하지 않음 (다음 EnterPlacementMode 시 설정)
    78→
    79→	OnPlacementModeChanged.Broadcast(CurrentMode);
    80→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Exited placement mode"));
    81→}
    82→
    83→void UWjWorldPlacementComponent::ToggleDeleteMode()
    84→{
    85→	if (CurrentMode == EPlacementMode::None)
    86→	{
    87→		return;
    88→	}
    89→
    90→	if (CurrentMode == EPlacementMode::Deleting)
    91→	{
    92→		// 삭제 모드 해제 → 배치 모드 복귀
    93→		if (HoveredObject)
    94→		{
    95→			HoveredObject->SetHighlighted(false);
    96→			HoveredObject = nullptr;
    97→		}
    98→		CurrentMode = EPlacementMode::Placing;
    99→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to placing mode"));
   100→	}
   101→	else
   102→	{
   103→		// 배치 모드 → 삭제 모드
   104→		DestroyPreview();
   105→		CurrentMode = EPlacementMode::Deleting;
   106→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to delete mode"));
   107→	}
   108→
   109→	OnPlacementModeChanged.Broadcast(CurrentMode);
   110→}
   111→
   112→void UWjWorldPlacementComponent::SelectObject(FName ObjectId)
   113→{
   114→	if (!Catalog)
   115→	{
   116→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: No catalog set"));
   117→		return;
   118→	}
   119→
   120→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(ObjectId);
   121→	if (!Def)
   122→	{
   123→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: ObjectId=%s not found in catalog"), *ObjectId.ToString());
   124→		return;
   125→	}
   126→
   127→	// 삭제 모드에서 선택하면 배치 모드로 전환
   128→	if (CurrentMode == EPlacementMode::Deleting)
   129→	{
   130→		if (HoveredObject)
   131→		{
   132→			HoveredObject->SetHighlighted(false);
   133→			HoveredObject = nullptr;
   134→		}
   135→		CurrentMode = EPlacementMode::Placing;
   136→		OnPlacementModeChanged.Broadcast(CurrentMode);
   137→	}
   138→
   139→	// 기존 프리뷰 제거 후 새로 생성
   140→	DestroyPreview();
   141→	SelectedObjectId = ObjectId;
   142→
   143→	UWorld* World = GetWorld();
   144→	if (World)
   145→	{
   146→		FActorSpawnParameters SpawnParams;
   147→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   148→		PreviewActor = World->SpawnActor<AWjWorldPlacementPreviewActor>(AWjWorldPlacementPreviewActor::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, SpawnParams);
   149→		if (PreviewActor)
   150→		{
   151→			PreviewActor->InitializePreview(*Def);
   152→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Preview created for ObjectId=%s"), *ObjectId.ToString());
   153→		}
   154→	}
   155→}
   156→
   157→void UWjWorldPlacementComponent::RotatePreview()
   158→{
   159→	if (PreviewActor && CurrentMode == EPlacementMode::Placing)
   160→	{
   161→		const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   162→		float SnapDegrees = Def ? Def->RotationSnapDegrees : 90.0f;
   163→		PreviewActor->RotatePreview(SnapDegrees);
   164→	}
   165→}
   166→
   167→void UWjWorldPlacementComponent::CycleRotationAxis()
   168→{
   169→	if (PreviewActor && CurrentMode == EPlacementMode::Placing)
   170→	{
   171→		PreviewActor->CycleRotationAxis();
   172→	}
   173→}
   174→
   175→void UWjWorldPlacementComponent::ConfirmPlacement()
   176→{
   177→	if (CurrentMode != EPlacementMode::Placing || !PreviewActor || !bCurrentPreviewValid)
   178→	{
   179→		return;
   180→	}
   181→
   182→	if (!Catalog)
   183→	{
   184→		return;
   185→	}
   186→
   187→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(SelectedObjectId);
   188→	if (!Def)
   189→	{
   190→		return;
   191→	}
   192→
   193→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   194→	if (!DataProvider)
   195→	{
   196→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   197→		return;
   198→	}
   199→
   200→	// 배치 데이터 생성
   201→	FVector SpawnLocation = PreviewActor->GetActorLocation();
   202→	FRotator SpawnRotation = PreviewActor->GetCurrentRotation();
   203→
   204→	FPlacedObjectSaveEntry Entry;
   205→	Entry.ObjectId = SelectedObjectId;
   206→	Entry.Transform = FTransform(SpawnRotation, SpawnLocation, Def->DefaultScale);
   207→
   208→	// DataProvider에 추가 (서버에서 스폰 + 클라이언트 리플리케이션)
   209→	DataProvider->AddPlacedObject(Entry);
   210→
   211→	// 로컬 SaveGame에도 저장 (호스트 영구 저장용)
   212→	SaveLayout();
   213→
   214→	OnObjectPlaced.Broadcast();
   215→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object placed - ObjectId=%s at %s (Context: %s)"),
   216→		*SelectedObjectId.ToString(), *SpawnLocation.ToString(), *GetPlacementContextName(CurrentContext));
   217→}
   218→
   219→void UWjWorldPlacementComponent::DeleteHoveredObject()
   220→{
   221→	if (CurrentMode != EPlacementMode::Deleting || !HoveredObject)
   222→	{
   223→		return;
   224→	}
   225→
   226→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   227→	if (!DataProvider)
   228→	{
   229→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   230→		return;
   231→	}
   232→
   233→	// DataProvider에서 해당 오브젝트 인덱스 찾기
   234→	int32 Index = FindPlacedObjectIndex(HoveredObject);
   235→	if (Index == INDEX_NONE)
   236→	{
   237→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Could not find object index for deletion"));
   238→		return;
   239→	}
   240→
   241→	HoveredObject = nullptr;
   242→
   243→	// DataProvider에서 제거 (서버에서 파괴 + 클라이언트 리플리케이션)
   244→	DataProvider->RemovePlacedObjectAt(Index);
   245→
   246→	// 로컬 SaveGame에도 저장
   247→	SaveLayout();
   248→
   249→	OnObjectDeleted.Broadcast();
   250→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object deleted at index %d"), Index);
   251→}
   252→
   253→void UWjWorldPlacementComponent::SetCatalog(UWjWorldPlaceableObjectDataAsset* InCatalog)
   254→{
   255→	Catalog = InCatalog;
   256→}
   257→
   258→void UWjWorldPlacementComponent::SaveLayout()
   259→{
   260→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   261→	// 클라이언트가 저장하면 다른 세션의 배치물이 섞이는 문제 발생
   262→	UWorld* World = GetWorld();
   263→	if (!World)
   264→	{
   265→		return;
   266→	}
   267→
   268→	ENetMode NetMode = World->GetNetMode();
   269→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   270→	{
   271→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayout skipped (not host)"));
   272→		return;
   273→	}
   274→
   275→	// DataProvider에서 데이터를 가져와 로컬 SaveGame에 저장 (호스트 영구 저장용)
   276→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   277→	if (!DataProvider)
   278→	{
   279→		return;
   280→	}
   281→
   282→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   283→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
