   378→	{
   379→		return false;
   380→	}
   381→
   382→	// SaveGame 로드
   383→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   384→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   385→	);
