   391→	}
   392→
   393→	// 컨텍스트 검증 (다른 컨텍스트의 레이아웃 로드 방지)
   394→	if (SaveGame->SavedContext != EPlacementContext::None && SaveGame->SavedContext != CurrentContext)
   395→	{
   396→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Context mismatch - slot '%s' is for '%s', current context is '%s'"),
   397→			*SlotName, *GetPlacementContextName(SaveGame->SavedContext), *GetPlacementContextName(CurrentContext));
   398→		return false;
