   419→	// SaveGame 디렉토리에서 모든 .sav 파일 검색
   420→	FString SaveDirectory = FPaths::ProjectSavedDir() / TEXT("SaveGames");
   421→
   422→	IFileManager& FileManager = IFileManager::Get();
   423→	TArray<FString> FoundFiles;
   424→	FileManager.FindFiles(FoundFiles, *SaveDirectory, TEXT("*.sav"));
   425→
   426→	for (const FString& FileName : FoundFiles)
   427→	{
   428→		// .sav 확장자 제거하여 슬롯 이름 추출
   429→		FString SlotName = FPaths::GetBaseFilename(FileName);
   430→
   431→		// SaveGame을 로드하여 컨텍스트 확인
   432→		UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
