   489→bool UWjWorldPlacementComponent::ExportLayoutAsCSV(const FString& FileName)
   490→{
   491→	// AW 컨텍스트에서만 동작
   492→	if (CurrentContext != EPlacementContext::ApproachingWall)
   493→	{
   494→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   495→		return false;
   496→	}
   497→
   498→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   499→	if (!DataProvider)
   500→	{
   501→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   502→		return false;
   503→	}
   504→
   505→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   506→	if (PlacedObjects.Num() == 0)
   507→	{
   508→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   509→		return false;
   510→	}
   511→
   512→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   513→	const FApproachingWallGridConfig GridConfig;
   514→	const FVector& BrickSize = GridConfig.BrickSize;
   515→
   516→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   517→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   518→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   519→
   520→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   521→	{
   522→		const FVector& Location = Entry.Transform.GetLocation();
   523→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   524→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   525→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   526→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   527→	}
   528→
   529→	// 2. 그리드 크기 계산 (+1 = 위치 개수, +2 = 양쪽 1셀 패딩)
   530→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1 + 2;
   531→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1 + 2;
   532→
   533→	// 최소 크기 보장
   534→	GridColumns = FMath::Max(GridColumns, 3);
   535→	GridRows = FMath::Max(GridRows, 3);
   536→
   537→	// 그리드 원점: MinBounds에서 1칸 앞 (패딩용, 오브젝트가 인덱스 1부터 매핑)
   538→	FVector GridOrigin = MinBounds - FVector(BrickSize.X, BrickSize.Y, 0.0f);
   539→
   540→	// 3. 그리드 초기화 (-1 = Empty)
   541→	TArray<TArray<int32>> Grid;
   542→	Grid.SetNum(GridRows);
   543→	for (int32 Row = 0; Row < GridRows; ++Row)
   544→	{
   545→		Grid[Row].SetNum(GridColumns);
   546→		for (int32 Col = 0; Col < GridColumns; ++Col)
   547→		{
   548→			Grid[Row][Col] = -1;
   549→		}
   550→	}
   551→
   552→	// 4. 오브젝트를 그리드에 매핑 (RoundToInt로 CalculateBrickGridIndex와 일치)
   553→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   554→	{
   555→		const FVector& Location = Entry.Transform.GetLocation();
   556→
   557→		// 월드 좌표 → 그리드 인덱스
   558→		int32 Col = FMath::RoundToInt((Location.X - GridOrigin.X) / BrickSize.X);
   559→		int32 Row = FMath::RoundToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   560→
   561→		// 범위 체크
   562→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   563→		{
   564→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   565→			Grid[Row][Col] = BrickTypeValue;
   566→		}
   567→	}
   568→
   569→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   570→	FString CSVContent;
   571→
   572→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   573→	// CalculateBrickPosition은 CenterOffset을 그리드 중심으로 사용하므로, 그리드 중심 좌표를 저장
   574→	FVector CenterOffset;
   575→	CenterOffset.X = GridOrigin.X + (GridColumns - 1) * 0.5f * BrickSize.X;
   576→	CenterOffset.Y = GridOrigin.Y + (GridRows - 1) * 0.5f * BrickSize.Y;
   577→	CenterOffset.Z = 0.0f;
   578→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   579→		CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   580→
   581→	for (int32 Row = 0; Row < GridRows; ++Row)
   582→	{
   583→		for (int32 Col = 0; Col < GridColumns; ++Col)
   584→		{
   585→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   586→			if (Col < GridColumns - 1)
   587→			{
   588→				CSVContent += TEXT(",");
   589→			}
   590→		}
   591→		CSVContent += TEXT("\n");
   592→	}
   593→
   594→	// 6. 파일 저장
   595→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   596→
   597→	// 디렉토리 생성
   598→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   599→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   600→	{
   601→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   602→	}
   603→
   604→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   605→
   606→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   607→	{
   608→		LastExportedCSVPath = FilePath;
   609→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportLayoutAsCSV: Exported to '%s' (Grid: %dx%d)"),
   610→			*FilePath, GridColumns, GridRows);
   611→		return true;
   612→	}
   613→	else
   614→	{
   615→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: Failed to save file '%s'"), *FilePath);
   616→		return false;
   617→	}
   618→}
