   620→bool UWjWorldPlacementComponent::ExportJumpMapLayoutAsCSV(const FString& FileName)
   621→{
   622→	if (CurrentContext != EPlacementContext::JumpMap)
   623→	{
   624→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: Only available in JumpMap context"));
   625→		return false;
   626→	}
   627→
   628→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   629→	if (!DataProvider)
   630→	{
   631→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: No data provider"));
   632→		return false;
   633→	}
   634→
   635→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   636→	if (PlacedObjects.Num() == 0)
   637→	{
   638→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: No objects to export"));
   639→		return false;
   640→	}
   641→
   642→	// CSV 생성: 헤더 + 오브젝트 행
   643→	FString CSVContent;
   644→	CSVContent += FString::Printf(TEXT("#META:MapName:%s\n"), *FileName);
   645→	CSVContent += TEXT("ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ\n");
   646→
   647→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   648→	{
   649→		const FVector& Loc = Entry.Transform.GetLocation();
   650→		const FRotator Rot = Entry.Transform.GetRotation().Rotator();
   651→		const FVector& Scale = Entry.Transform.GetScale3D();
   652→
   653→		CSVContent += FString::Printf(TEXT("%s,%f,%f,%f,%f,%f,%f,%f,%f,%f\n"),
   654→			*Entry.ObjectId.ToString(),
   655→			Loc.X, Loc.Y, Loc.Z,
   656→			Rot.Pitch, Rot.Yaw, Rot.Roll,
   657→			Scale.X, Scale.Y, Scale.Z);
   658→	}
   659→
   660→	// 파일 저장
   661→	FString UserLayoutDir = GetUserJumpMapLayoutDirectory();
   662→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   663→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   664→	{
   665→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   666→	}
   667→
   668→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   669→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   670→	{
   671→		LastExportedCSVPath = FilePath;
   672→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportJumpMapLayoutAsCSV: Exported to '%s' (%d objects)"),
   673→			*FilePath, PlacedObjects.Num());
   674→		return true;
   675→	}
   676→
   677→	UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: Failed to save '%s'"), *FilePath);
   678→	return false;
   679→}
