   681→void UWjWorldPlacementComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
   682→{
   683→	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
   684→
   685→	if (CurrentMode == EPlacementMode::Placing && PreviewActor)
   686→	{
   687→		const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   688→		float GroundOffset = Def ? Def->GroundOffset : 0.0f;
   689→		FVector PlaceLocation;
   690→		bool bTraceSuccess = false;
   691→
   692→		if (bAirPlacementMode)
   693→		{
   694→			// Air 모드: 수평 평면과 교차
   695→			FVector AirLocation;
   696→			if (TraceAirPlane(AirLocation))
   697→			{
   698→				PlaceLocation = AirLocation + FVector(0.0f, 0.0f, GroundOffset);
   699→				bTraceSuccess = true;
   700→			}
   701→		}
   702→		else
   703→		{
   704→			// Ground 모드: 기존 바닥 트레이스
   705→			FHitResult HitResult;
   706→			if (TraceGroundUnderMouse(HitResult))
   707→			{
   708→				PlaceLocation = HitResult.ImpactPoint + FVector(0.0f, 0.0f, GroundOffset);
   709→				bTraceSuccess = true;
   710→			}
   711→		}
   712→
   713→		if (bTraceSuccess)
   714→		{
   715→			// AW 컨텍스트: 그리드 스냅 적용
   716→			if (CurrentContext == EPlacementContext::ApproachingWall)
   717→			{
   718→				PlaceLocation = SnapToGrid(PlaceLocation);
   719→			}
   720→
   721→			FRotator PlaceRotation = PreviewActor->GetCurrentRotation();
   722→			PreviewActor->UpdatePreviewTransform(PlaceLocation, PlaceRotation);
   723→
   724→			// 유효성 검사
   725→			bCurrentPreviewValid = IsPlacementLocationValid(PlaceLocation);
   726→			PreviewActor->SetPreviewValid(bCurrentPreviewValid);
   727→		}
   728→		else
   729→		{
   730→			bCurrentPreviewValid = false;
   731→			PreviewActor->SetPreviewValid(false);
   732→		}
   733→	}
   734→	else if (CurrentMode == EPlacementMode::Deleting)
   735→	{
   736→		// 삭제 모드: 호버 대상 갱신
   737→		AWjWorldPlacedObjectActor* NewHovered = TraceForPlacedObject();
   738→
   739→		if (NewHovered != HoveredObject)
   740→		{
   741→			if (HoveredObject)
   742→			{
   743→				HoveredObject->SetHighlighted(false);
   744→			}
   745→			HoveredObject = NewHovered;
   746→			if (HoveredObject)
   747→			{
   748→				HoveredObject->SetHighlighted(true);
   749→			}
   750→		}
   751→	}
   752→}
   753→
   754→bool UWjWorldPlacementComponent::TraceGroundUnderMouse(FHitResult& OutHit) const
   755→{
   756→	APlayerController* PC = GetPlayerController();
   757→	if (!PC)
   758→	{
   759→		return false;
   760→	}
   761→
   762→	FVector WorldLocation, WorldDirection;
   763→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   764→	{
   765→		return false;
   766→	}
   767→
   768→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   769→
   770→	FCollisionQueryParams QueryParams;
   771→	QueryParams.bTraceComplex = false;
   772→	QueryParams.AddIgnoredActor(GetOwner());
   773→	if (PreviewActor)
   774→	{
   775→		QueryParams.AddIgnoredActor(PreviewActor);
   776→	}
   777→
   778→	return GetWorld()->LineTraceSingleByChannel(OutHit, WorldLocation, TraceEnd, ECC_Visibility, QueryParams);
   779→}
   780→
   781→bool UWjWorldPlacementComponent::TraceAirPlane(FVector& OutLocation) const
   782→{
   783→	APlayerController* PC = GetPlayerController();
   784→	if (!PC)
   785→	{
   786→		return false;
   787→	}
   788→
   789→	FVector WorldLoc, WorldDir;
   790→	if (!PC->DeprojectMousePositionToWorld(WorldLoc, WorldDir))
   791→	{
   792→		return false;
   793→	}
   794→
   795→	// Ray-plane intersection: Plane at Z = AirPlaneHeight, Normal = UpVector
   796→	float Denom = FVector::DotProduct(WorldDir, FVector::UpVector);
   797→	if (FMath::Abs(Denom) < KINDA_SMALL_NUMBER)
   798→	{
   799→		return false; // 레이가 평면과 평행
   800→	}
   801→
   802→	float T = (AirPlaneHeight - WorldLoc.Z) / Denom;
   803→	if (T < 0.f || T > MaxAirTraceDistance)
   804→	{
   805→		return false; // 뒤쪽이거나 너무 먼 교차점
   806→	}
   807→
   808→	OutLocation = WorldLoc + WorldDir * T;
   809→	return true;
   810→}
   811→
   812→bool UWjWorldPlacementComponent::IsPlacementLocationValid(const FVector& Location) const
   813→{
   814→	UWorld* World = GetWorld();
   815→	if (!World)
   816→	{
   817→		return false;
   818→	}
   819→
   820→	// AW 컨텍스트: 그리드 스냅 사용 시 더 작은 반경으로 정확히 같은 위치만 체크
   821→	// 일반 컨텍스트: 기존 겹침 반경 사용
   822→	float CheckRadius = (CurrentContext == EPlacementContext::ApproachingWall)
   823→		? GridOverlapCheckRadius
   824→		: OverlapCheckRadius;
   825→
   826→	// 겹침 체크: 기존 배치된 오브젝트와 겹치는지
   827→	TArray<FOverlapResult> Overlaps;
   828→	FCollisionQueryParams QueryParams;
   829→	QueryParams.AddIgnoredActor(GetOwner());
   830→	if (PreviewActor)
   831→	{
   832→		QueryParams.AddIgnoredActor(PreviewActor);
   833→	}
   834→
   835→	FCollisionShape SphereShape = FCollisionShape::MakeSphere(CheckRadius);
   836→	World->OverlapMultiByChannel(Overlaps, Location, FQuat::Identity, ECC_Visibility, SphereShape, QueryParams);
   837→
   838→	for (const FOverlapResult& Overlap : Overlaps)
   839→	{
   840→		if (Cast<AWjWorldPlacedObjectActor>(Overlap.GetActor()))
   841→		{
   842→			return false;
   843→		}
   844→	}
   845→
   846→	return true;
   847→}
   848→
   849→FVector UWjWorldPlacementComponent::SnapToGrid(const FVector& Location) const
   850→{
   851→	// AW 그리드 설정 사용
   852→	const FApproachingWallGridConfig GridConfig;
   853→	const FVector& BrickSize = GridConfig.BrickSize;
   854→
   855→	// 그리드 스냅: 각 축을 BrickSize 단위로 반올림
   856→	FVector SnappedLocation;
   857→	SnappedLocation.X = FMath::RoundToFloat(Location.X / BrickSize.X) * BrickSize.X;
   858→	SnappedLocation.Y = FMath::RoundToFloat(Location.Y / BrickSize.Y) * BrickSize.Y;
   859→	SnappedLocation.Z = Location.Z; // Z축은 스냅하지 않음 (바닥 높이 유지)
   860→
   861→	return SnappedLocation;
   862→}
