   877→
   878→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   879→
   880→	FHitResult HitResult;
   881→	FCollisionQueryParams QueryParams;
   882→	QueryParams.bTraceComplex = false;
   883→	QueryParams.AddIgnoredActor(GetOwner());
