  1012→		}
  1013→		if (RotateAction)
  1014→		{
  1015→			EIC->BindAction(RotateAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnRotateAction);
  1016→		}
  1017→		if (DeleteAction)
  1018→		{
  1019→			EIC->BindAction(DeleteAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnDeleteAction);
  1020→		}
  1021→		if (ScrollAction)
  1022→		{
  1023→			EIC->BindAction(ScrollAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnScrollAction);
  1024→		}
  1025→		if (ToggleAirModeAction)
  1026→		{
  1027→			EIC->BindAction(ToggleAirModeAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnToggleAirModeAction);
  1028→		}
  1029→		if (CycleAxisAction)
