  1168→int32 UWjWorldPlacementComponent::FindPlacedObjectIndex(AWjWorldPlacedObjectActor* Actor) const
  1169→{
  1170→	if (!Actor)
  1171→	{
  1172→		return INDEX_NONE;
  1173→	}
  1174→
  1175→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
  1176→	if (!DataProvider)
  1177→	{
  1178→		return INDEX_NONE;
  1179→	}
  1180→
  1181→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
  1182→	FName TargetId = Actor->GetObjectId();
  1183→	FVector TargetLocation = Actor->GetActorLocation();
  1184→
  1185→	// ObjectId와 위치로 매칭 (동일 ObjectId가 여러 개 있을 수 있으므로 위치도 체크)
  1186→	for (int32 i = 0; i < PlacedObjects.Num(); ++i)
  1187→	{
  1188→		const FPlacedObjectSaveEntry& Entry = PlacedObjects[i];
  1189→		if (Entry.ObjectId == TargetId)
  1190→		{
  1191→			// 위치가 가까우면 매치
  1192→			if (FVector::DistSquared(Entry.Transform.GetLocation(), TargetLocation) < 100.0f)
  1193→			{
  1194→				return i;
  1195→			}
  1196→		}
  1197→	}
  1198→
  1199→	return INDEX_NONE;
  1200→}
