   163→bool FWjWorldWallDescription::FindStartingEmptyCell(int32& OutX, int32& OutY)
   164→{
   165→    // 1. 먼저 경계에서 Flood Fill로 외부 영역 마킹
   166→    TSet<FIntPoint> ExteriorCells;
   167→    MarkExteriorCells(ExteriorCells);
   168→
   169→    // 2. 외부 영역이 아닌 내부 빈 셀 찾기
   170→    for (int32 Y = 0; Y < WallLayout.Num(); ++Y)
   171→    {
   172→        for (int32 X = 0; X < WallLayout[Y].Num(); ++X)
   173→        {
   174→            // 빈 셀이면서 외부 영역이 아닌 경우 = 내부 영역
   175→            if (WallLayout[Y][X] == WallCell_Empty && !ExteriorCells.Contains(FIntPoint(X, Y)))
   176→            {
   177→                OutX = X;
   178→                OutY = Y;
   179→                return true;
   180→            }
   181→        }
   182→    }
   183→
   184→    return false;
   185→}
   186→
   187→void FWjWorldWallDescription::MarkExteriorCells(TSet<FIntPoint>& OutExteriorCells)
   188→{
   189→    OutExteriorCells.Empty();
   190→
   191→    const int32 Rows = WallLayout.Num();
   192→    if (Rows == 0) return;
   193→
   194→    const int32 Cols = WallLayout[0].Num();
   195→    if (Cols == 0) return;
   196→
   197→    // 벽 밀폐 검증용: 4방향만 사용 (벽은 직교 방향만 막음, 대각선 틈새는 밀폐로 인정)
   198→    const TArray<FIntPoint> Directions = {
   199→        { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 }
   200→    };
   201→
   202→    TQueue<FIntPoint> Queue;
   203→
   204→    // 경계(가장자리)에 있는 모든 빈 셀을 시작점으로 추가
   205→    // 상단/하단 행
   206→    for (int32 X = 0; X < Cols; ++X)
   207→    {
   208→        if (WallLayout[0][X] == WallCell_Empty)
   209→        {
   210→            FIntPoint Pt(X, 0);
   211→            if (!OutExteriorCells.Contains(Pt))
   212→            {
   213→                OutExteriorCells.Add(Pt);
   214→                Queue.Enqueue(Pt);
   215→            }
   216→        }
   217→        if (WallLayout[Rows - 1][X] == WallCell_Empty)
   218→        {
   219→            FIntPoint Pt(X, Rows - 1);
   220→            if (!OutExteriorCells.Contains(Pt))
   221→            {
   222→                OutExteriorCells.Add(Pt);
   223→                Queue.Enqueue(Pt);
   224→            }
   225→        }
   226→    }
   227→
   228→    // 좌측/우측 열
   229→    for (int32 Y = 0; Y < Rows; ++Y)
   230→    {
   231→        if (WallLayout[Y][0] == WallCell_Empty)
   232→        {
   233→            FIntPoint Pt(0, Y);
   234→            if (!OutExteriorCells.Contains(Pt))
   235→            {
   236→                OutExteriorCells.Add(Pt);
   237→                Queue.Enqueue(Pt);
   238→            }
   239→        }
   240→        if (WallLayout[Y][Cols - 1] == WallCell_Empty)
   241→        {
   242→            FIntPoint Pt(Cols - 1, Y);
   243→            if (!OutExteriorCells.Contains(Pt))
   244→            {
   245→                OutExteriorCells.Add(Pt);
   246→                Queue.Enqueue(Pt);
   247→            }
   248→        }
   249→    }
   250→
   251→    // Flood Fill: 경계에서 연결된 모든 빈 셀을 외부로 마킹
   252→    while (!Queue.IsEmpty())
   253→    {
   254→        FIntPoint Current;
   255→        Queue.Dequeue(Current);
   256→
   257→        for (const FIntPoint& Dir : Directions)
   258→        {
   259→            const int32 NX = Current.X + Dir.X;
   260→            const int32 NY = Current.Y + Dir.Y;
   261→
   262→            // 범위 체크
   263→            if (NX < 0 || NX >= Cols || NY < 0 || NY >= Rows)
   264→                continue;
   265→
   266→            // 벽이면 통과 불가
   267→            if (WallLayout[NY][NX] >= 1)
   268→                continue;
   269→
   270→            FIntPoint Next(NX, NY);
   271→            if (!OutExteriorCells.Contains(Next))
   272→            {
   273→                OutExteriorCells.Add(Next);
   274→                Queue.Enqueue(Next);
   275→            }
   276→        }
   277→    }
   278→}
