   343→int32 UWjWorldWallDescriptionDataAsset::ScanUserWallLayouts(TArray<FWjWorldWallDescription>& OutUserDescriptions) const
   344→{
   345→    OutUserDescriptions.Empty();
   346→
   347→    FString UserLayoutDir = GetUserWallLayoutDirectory();
   348→
   349→    // 디렉토리 존재 확인
   350→    IFileManager& FileManager = IFileManager::Get();
   351→    if (!FileManager.DirectoryExists(*UserLayoutDir))
   352→    {
   353→        UE_LOG(LogWjWorld, Log, TEXT("ScanUserWallLayouts: User layout directory does not exist: %s"), *UserLayoutDir);
   354→        return 0;
   355→    }
   356→
   357→    // CSV 파일 검색
   358→    TArray<FString> FoundFiles;
   359→    FileManager.FindFiles(FoundFiles, *UserLayoutDir, TEXT("*.csv"));
   360→
   361→    for (const FString& FileName : FoundFiles)
   362→    {
   363→        FString FileNameNoExt = FPaths::GetBaseFilename(FileName);
   364→        FString FullPath = UserLayoutDir / FileName;
   365→
   366→        FWjWorldWallDescription UserDesc;
   367→        UserDesc.WallName = FString::Printf(TEXT("User_%s"), *FileNameNoExt);
   368→        UserDesc.WallLayoutFilePath.FilePath = FullPath;
   369→        UserDesc.BrickSize = FVector(100.0, 100.0, 100.0);  // 기본값
   370→        UserDesc.CenterOffset = FVector::ZeroVector;
   371→
   372→        // ⭐ CSV 파일에서 메타데이터 읽기 (CenterOffset)
   373→        FString FileContent;
   374→        if (FFileHelper::LoadFileToString(FileContent, *FullPath))
   375→        {
   376→            TArray<FString> Lines;
   377→            FileContent.ParseIntoArrayLines(Lines);
   378→
   379→            for (const FString& Line : Lines)
   380→            {
   381→                if (Line.StartsWith(TEXT("#META:CenterOffset:")))
   382→                {
   383→                    FString OffsetStr = Line.RightChop(19); // "#META:CenterOffset:" 제거
   384→                    TArray<FString> Components;
   385→                    OffsetStr.ParseIntoArray(Components, TEXT(","));
   386→
   387→                    if (Components.Num() == 3)
   388→                    {
   389→                        UserDesc.CenterOffset.X = FCString::Atof(*Components[0]);
   390→                        UserDesc.CenterOffset.Y = FCString::Atof(*Components[1]);
   391→                        UserDesc.CenterOffset.Z = FCString::Atof(*Components[2]);
   392→                        UE_LOG(LogWjWorld, Log, TEXT("ScanUserWallLayouts: Parsed CenterOffset (%.1f, %.1f, %.1f) for '%s'"),
   393→                            UserDesc.CenterOffset.X, UserDesc.CenterOffset.Y, UserDesc.CenterOffset.Z, *UserDesc.WallName);
   394→                    }
   395→                    break;
   396→                }
   397→            }
   398→        }
   399→
   400→        OutUserDescriptions.Add(UserDesc);
   401→        UE_LOG(LogWjWorld, Log, TEXT("ScanUserWallLayouts: Found user layout '%s'"), *UserDesc.WallName);
   402→    }
   403→
   404→    return OutUserDescriptions.Num();
   405→}
