   407→TArray<FString> UWjWorldWallDescriptionDataAsset::GetAllWallNames() const
   408→{
   409→    TArray<FString> AllNames;
   410→
   411→    // 내장 레이아웃
   412→    for (const FWjWorldWallDescription& Desc : WallDescriptions)
   413→    {
   414→        AllNames.Add(Desc.WallName);
   415→    }
   416→
   417→    // 유저 레이아웃
   418→    if (!bUserDescriptionsCached)
   419→    {
   420→        ScanUserWallLayouts(CachedUserDescriptions);
   421→        bUserDescriptionsCached = true;
   422→    }
   423→
   424→    for (const FWjWorldWallDescription& UserDesc : CachedUserDescriptions)
   425→    {
   426→        AllNames.Add(UserDesc.WallName);
   427→    }
   428→
   429→    return AllNames;
   430→}
