   256→void UWaitingRoomHUDWidget::UpdateRoomInfo(const FRoomSettings* InSettings)
   257→{
   258→	// 설정이 직접 전달되면 사용, 아니면 GameState에서 읽음
   259→	FRoomSettings Settings;
   260→	if (InSettings)
   261→	{
   262→		Settings = *InSettings;
   263→	}
   264→	else if (CachedGameState)
   265→	{
   266→		Settings = CachedGameState->GetRoomSettings();
   267→	}
   268→	else
   269→	{
   270→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdateRoomInfo - CachedGameState is NULL"));
   271→		return;
   272→	}
   273→
   274→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdateRoomInfo - Updating with: RoomName='%s', GameMode='%s', MapName='%s'"),
   275→		*Settings.RoomName, *Settings.GameMode, *Settings.MapName);
   276→
   277→	// 방 이름 표시
   278→	if (RoomNameText)
   279→	{
   280→		RoomNameText->SetText(FText::FromString(Settings.RoomName));
   281→	}
   282→
   283→	// 게임 모드 표시
   284→	if (GameModeText)
   285→	{
   286→		GameModeText->SetText(FText::FromString(Settings.GameMode));
   287→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: GameModeText set to '%s'"), *Settings.GameMode);
   288→	}
   289→
   290→	// 맵 이름 표시
   291→	if (MapText)
   292→	{
   293→		FString MapDisplayName = Settings.MapName;
   294→		// User_ 접두사 제거하여 표시
   295→		MapDisplayName.RemoveFromStart(TEXT("User_"));
   296→		MapText->SetText(FText::FromString(MapDisplayName));
   297→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: MapText set to '%s'"), *MapDisplayName);
   298→	}
   299→
   300→	// ⭐ 플레이어 수 표시 (실시간으로 가져오기)
   301→	if (PlayerCountText && CachedGameState)
   302→	{
   303→		int32 CurrentPlayers = CachedGameState->GetPlayerCount();
   304→		int32 MaxPlayers = Settings.MaxPlayers;
   305→
   306→		FString PlayerCountStr = FString::Printf(TEXT("%d / %d"), CurrentPlayers, MaxPlayers);
   307→		PlayerCountText->SetText(FText::FromString(PlayerCountStr));
   308→
   309→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: PlayerCountText set to '%s'"), *PlayerCountStr);
   310→	}
   311→
   312→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Room info updated successfully"));
   313→}
