   315→void UWaitingRoomHUDWidget::UpdatePlayerList()
   316→{
   317→	if (!CachedGameState || !PlayerListContainer)
   318→	{
   319→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdatePlayerList - GameState or Container is NULL"));
   320→		return;
   321→	}
   322→
   323→	// 기존 목록 제거
   324→	PlayerListContainer->ClearChildren();
   325→	PlayerButtonToIDMap.Empty();
   326→
   327→	// 플레이어 목록 가져오기 & 캐시
   328→	CachedPlayerDisplayList = CachedGameState->GetPlayerList();
   329→
   330→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Updating player list - %d players"), CachedPlayerDisplayList.Num());
   331→
   332→	// 버튼으로 표시 (클릭 시 프로필 팝업)
   333→	for (const FPlayerDisplayInfo& Info : CachedPlayerDisplayList)
   334→	{
   335→		UButton* PlayerButton = NewObject<UButton>(this);
   336→		if (!PlayerButton)
   337→		{
   338→			continue;
   339→		}
   340→
   341→		// 버튼 안에 텍스트 추가
   342→		UTextBlock* PlayerText = NewObject<UTextBlock>(this);
   343→		if (PlayerText)
   344→		{
   345→			FString DisplayText = Info.PlayerName;
   346→
   347→			if (Info.bIsHost)
   348→			{
   349→				DisplayText = FString::Printf(TEXT("[Host] %s"), *DisplayText);
   350→			}
   351→
   352→			if (Info.bIsReady)
   353→			{
   354→				DisplayText += TEXT(" (Ready)");
   355→			}
   356→
   357→			PlayerText->SetText(FText::FromString(DisplayText));
   358→			PlayerButton->AddChild(PlayerText);
   359→		}
   360→
   361→		// 버튼 → PlayerID 매핑 저장
   362→		PlayerButtonToIDMap.Add(PlayerButton, Info.PlayerID);
   363→
   364→		// 모든 버튼에 공통 핸들러 바인딩
   365→		PlayerButton->OnClicked.AddDynamic(this, &UWaitingRoomHUDWidget::OnAnyPlayerButtonClicked);
   366→
   367→		PlayerListContainer->AddChild(PlayerButton);
   368→
   369→		UE_LOG(LogWjWorld, Warning, TEXT("  - %s (ID: %d)"), *Info.PlayerName, Info.PlayerID);
   370→	}
   371→}
