   395→void UWaitingRoomHUDWidget::ShowPlayerProfile(int32 PlayerID)
   396→{
   397→	if (!CachedGameState)
   398→	{
   399→		return;
   400→	}
   401→
   402→	// PlayerID로 PlayerState 검색
   403→	APlayerState* TargetPS = nullptr;
   404→	for (APlayerState* PS : CachedGameState->PlayerArray)
   405→	{
   406→		if (PS && PS->GetPlayerId() == PlayerID)
   407→		{
   408→			TargetPS = PS;
   409→			break;
   410→		}
   411→	}
   412→
   413→	if (!TargetPS)
   414→	{
   415→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: PlayerState not found for ID %d"), PlayerID);
   416→		return;
   417→	}
   418→
   419→	// 프로필 위젯 생성
   420→	if (!ProfileWidgetClass)
   421→	{
   422→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: ProfileWidgetClass is not set"));
   423→		return;
   424→	}
   425→
   426→	if (!ProfileWidgetInstance)
   427→	{
   428→		ProfileWidgetInstance = CreateWidget<UPlayerProfileWidget>(GetOwningPlayer(), ProfileWidgetClass);
   429→		if (ProfileWidgetInstance)
   430→		{
   431→			ProfileWidgetInstance->AddToViewport(100);
   432→		}
   433→	}
   434→
   435→	if (!ProfileWidgetInstance)
   436→	{
   437→		return;
   438→	}
   439→
   440→	// 자기 자신인지 확인
   441→	APlayerController* LocalPC = GetOwningPlayer();
   442→	if (LocalPC && LocalPC->PlayerState && LocalPC->PlayerState->GetPlayerId() == PlayerID)
   443→	{
   444→		// 자기 자신 → ShowLocalProfile
   445→		ProfileWidgetInstance->ShowLocalProfile();
   446→	}
   447→	else
   448→	{
   449→		// 타 플레이어
   450→		AWjWorldPlayerStateBase* BasePS = Cast<AWjWorldPlayerStateBase>(TargetPS);
   451→		FUniqueNetIdRepl UniqueId = TargetPS->GetUniqueId();
   452→		FText PlayerName = FText::FromString(TargetPS->GetPlayerName());
   453→		FCosmeticLoadout Loadout;
   454→		if (BasePS)
   455→		{
   456→			Loadout = BasePS->GetCosmeticLoadout();
   457→		}
   458→
   459→		ProfileWidgetInstance->ShowPlayerProfile(UniqueId, PlayerName, Loadout);
   460→	}
   461→
   462→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: ShowPlayerProfile for ID %d"), PlayerID);
   463→}
