   501→	// 호스트 여부 확인
   502→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   503→	if (!GameInstance || !GameInstance->GetSessionManager())
   504→	{
   505→		return;
   506→	}
