   510→	if (bIsHost)
   511→	{
   512→		// 호스트는 모든 플레이어가 준비되었을 때만 게임 시작 가능
   513→		bool bAllReady = CachedGameState->AreAllPlayersReady();
   514→		int32 PlayerCount = CachedGameState->GetPlayerCount();
