   519→		StartGameButton->SetIsEnabled(bCanStart);
   520→		
   521→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Start button enabled = %d (AllReady=%d, Count=%d)"),
