   578→void UWaitingRoomHUDWidget::UpdateHostSettingsPanelVisibility()
   579→{
   580→	if (!HostSettingsPanel)
   581→	{
   582→		return;
   583→	}
   584→
   585→	bool bIsHost = false;
   586→
   587→	// 1. SessionManager에서 호스트 여부 확인
   588→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   589→	if (GameInstance && GameInstance->GetSessionManager())
   590→	{
   591→		bIsHost = GameInstance->GetSessionManager()->IsHost();
   592→	}
   593→
   594→	// 2. 추가 검증: Listen Server인지 확인 (클라이언트에서 잘못된 bIsHost 값 방지)
   595→	UWorld* World = GetWorld();
   596→	if (World)
   597→	{
   598→		ENetMode NetMode = World->GetNetMode();
   599→		// 클라이언트(NM_Client)는 절대 호스트가 아님
   600→		if (NetMode == NM_Client)
   601→		{
   602→			bIsHost = false;
   603→		}
   604→		// Listen Server(NM_ListenServer)만 호스트임
   605→		else if (NetMode == NM_ListenServer || NetMode == NM_DedicatedServer)
   606→		{
   607→			// SessionManager 값 유지
   608→		}
   609→		else if (NetMode == NM_Standalone)
   610→		{
   611→			// 싱글플레이는 호스트 설정 불필요
   612→			bIsHost = false;
   613→		}
   614→	}
   615→
   616→	// 호스트만 설정 패널 표시 (클라이언트는 Display Text로 확인)
   617→	HostSettingsPanel->SetVisibility(bIsHost ? ESlateVisibility::Visible : ESlateVisibility::Collapsed);
   618→
   619→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: HostSettingsPanel visible=%s (bIsHost=%d, NetMode=%d)"),
   620→		bIsHost ? TEXT("Yes") : TEXT("No"), bIsHost, World ? (int32)World->GetNetMode() : -1);
   621→}
