   623→void UWaitingRoomHUDWidget::UpdateMapComboBoxForGameMode(const FString& GameModeId)
   624→{
   625→	if (!MapComboBox)
   626→	{
   627→		return;
   628→	}
   629→
   630→	MapComboBox->ClearOptions();
   631→	MapOptionDisplayToValue.Empty();
   632→
   633→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   634→	if (!DevSettings || DevSettings->MinigameCatalog.IsNull())
   635→	{
   636→		return;
   637→	}
   638→
   639→	UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   640→	if (!Catalog)
   641→	{
   642→		return;
   643→	}
   644→
   645→	const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*GameModeId));
   646→	if (Def)
   647→	{
   648→		for (const FWjWorldMinigameMapOption& Option : Def->MapOptions)
   649→		{
   650→			FString DisplayName = Option.DisplayName.ToString();
   651→			FString OptionValue = Option.OptionValue;
   652→
   653→			MapComboBox->AddOption(DisplayName);
   654→			MapOptionDisplayToValue.Add(DisplayName, OptionValue);
   655→		}
   656→	}
   657→
   658→	// ApproachingWall인 경우 유저 레이아웃도 추가
   659→	if (GameModeId == TEXT("ApproachingWall"))
   660→	{
   661→		if (!DevSettings->WallDescriptionAsset.IsNull())
   662→		{
   663→			UWjWorldWallDescriptionDataAsset* WallAsset = DevSettings->WallDescriptionAsset.LoadSynchronous();
   664→			if (WallAsset)
   665→			{
   666→				TArray<FWjWorldWallDescription> UserLayouts;
   667→				WallAsset->ScanUserWallLayouts(UserLayouts);
   668→
   669→				for (const FWjWorldWallDescription& Layout : UserLayouts)
   670→				{
   671→					FString DisplayName = Layout.WallName;
   672→					DisplayName.RemoveFromStart(TEXT("User_"));
   673→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   674→
   675→					MapComboBox->AddOption(DisplayStr);
   676→					MapOptionDisplayToValue.Add(DisplayStr, Layout.WallName);
   677→				}
   678→
   679→				UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Added %d user layouts"), UserLayouts.Num());
   680→			}
   681→		}
   682→	}
   683→
   684→	if (MapComboBox->GetOptionCount() > 0)
   685→	{
   686→		MapComboBox->SetSelectedIndex(0);
   687→	}
   688→
   689→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Map options updated for GameMode '%s' - %d options"),
   690→		*GameModeId, MapComboBox->GetOptionCount());
   691→}
