   726→	{
   727→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Only host can change settings (IsHost=%d)"),
   728→			GameInstance && GameInstance->GetSessionManager() ? GameInstance->GetSessionManager()->IsHost() : false);
   729→		return;
   730→	}
   731→
   732→	FRoomSettings OldSettings = CachedGameState->GetRoomSettings();
   733→	FRoomSettings NewSettings = OldSettings;
   734→
   735→	FString SelectedGameMode = GameModeComboBox->GetSelectedOption();
   736→	NewSettings.GameMode = SelectedGameMode;
   737→
   738→	FString SelectedMapDisplay = MapComboBox->GetSelectedOption();
   739→	if (const FString* MapValue = MapOptionDisplayToValue.Find(SelectedMapDisplay))
   740→	{
   741→		NewSettings.MapName = *MapValue;
   742→	}
   743→	else
   744→	{
   745→		NewSettings.MapName = SelectedMapDisplay;
   746→	}
   747→
   748→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Applying settings change:"));
   749→	UE_LOG(LogWjWorld, Warning, TEXT("  GameMode: '%s' -> '%s'"), *OldSettings.GameMode, *NewSettings.GameMode);
   750→	UE_LOG(LogWjWorld, Warning, TEXT("  MapName: '%s' -> '%s'"), *OldSettings.MapName, *NewSettings.MapName);
   751→
   752→	CachedGameState->UpdateRoomSettings(NewSettings);
   753→
   754→	// ⭐ 호스트 로컬에서 Display Text 직접 업데이트 (델리게이트 타이밍 안전장치)
   755→	UpdateRoomInfo(&NewSettings);
   756→
   757→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget::OnApplySettingsClicked END ==="));
   758→}
