   760→void UWaitingRoomHUDWidget::ApplyCurrentUISettings()
   761→{
   762→	// 호스트가 아니면 무시
   763→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   764→	if (!GameInstance || !GameInstance->GetSessionManager() || !GameInstance->GetSessionManager()->IsHost())
   765→	{
   766→		return;
   767→	}
   768→
   769→	// 필요한 컴포넌트가 없으면 무시
   770→	if (!CachedGameState || !GameModeComboBox || !MapComboBox)
   771→	{
   772→		return;
   773→	}
   774→
   775→	FRoomSettings NewSettings = CachedGameState->GetRoomSettings();
   776→
   777→	// 현재 UI에서 선택된 게임 모드
   778→	FString SelectedGameMode = GameModeComboBox->GetSelectedOption();
   779→	if (!SelectedGameMode.IsEmpty())
   780→	{
   781→		NewSettings.GameMode = SelectedGameMode;
   782→	}
   783→
   784→	// 현재 UI에서 선택된 맵
   785→	FString SelectedMapDisplay = MapComboBox->GetSelectedOption();
   786→	if (const FString* MapValue = MapOptionDisplayToValue.Find(SelectedMapDisplay))
   787→	{
   788→		NewSettings.MapName = *MapValue;
   789→	}
   790→	else if (!SelectedMapDisplay.IsEmpty())
   791→	{
   792→		NewSettings.MapName = SelectedMapDisplay;
   793→	}
   794→
   795→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Auto-applying UI settings before game start - GameMode: '%s', Map: '%s'"),
   796→		*NewSettings.GameMode, *NewSettings.MapName);
   797→
   798→	CachedGameState->UpdateRoomSettings(NewSettings);
   799→}
