    71→	{
    72→		PlayerData->SetCurrentCheckpointIndex(CheckpointOrder);
    73→		UE_LOG(LogWjWorld, Log, TEXT("JumpMapCheckpoint[%d]: Player [%s] reached checkpoint"),
    74→			CheckpointOrder, *Character->GetName());
    75→	}
    76→}
