   511→bool UWjWorldPlacementComponent::ExportLayoutAsCSV(const FString& FileName)
   512→{
   513→	// AW 컨텍스트에서만 동작
   514→	if (CurrentContext != EPlacementContext::ApproachingWall)
   515→	{
   516→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   517→		return false;
   518→	}
   519→
   520→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   521→	if (!DataProvider)
   522→	{
   523→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   524→		return false;
   525→	}
   526→
   527→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   528→	if (PlacedObjects.Num() == 0)
   529→	{
   530→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   531→		return false;
   532→	}
   533→
   534→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   535→	const FApproachingWallGridConfig GridConfig;
   536→	const FVector& BrickSize = GridConfig.BrickSize;
   537→
   538→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   539→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   540→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   541→
   542→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   543→	{
   544→		const FVector& Location = Entry.Transform.GetLocation();
   545→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   546→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   547→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   548→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   549→	}
   550→
   551→	// 2. 그리드 크기 계산 (+1 = 위치 개수, +2 = 양쪽 1셀 패딩)
   552→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1 + 2;
   553→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1 + 2;
   554→
   555→	// 최소 크기 보장
   556→	GridColumns = FMath::Max(GridColumns, 3);
   557→	GridRows = FMath::Max(GridRows, 3);
   558→
   559→	// 그리드 원점: MinBounds에서 1칸 앞 (패딩용, 오브젝트가 인덱스 1부터 매핑)
   560→	FVector GridOrigin = MinBounds - FVector(BrickSize.X, BrickSize.Y, 0.0f);
   561→
   562→	// 3. 그리드 초기화 (-1 = Empty)
   563→	TArray<TArray<int32>> Grid;
   564→	Grid.SetNum(GridRows);
   565→	for (int32 Row = 0; Row < GridRows; ++Row)
   566→	{
   567→		Grid[Row].SetNum(GridColumns);
   568→		for (int32 Col = 0; Col < GridColumns; ++Col)
   569→		{
   570→			Grid[Row][Col] = -1;
   571→		}
   572→	}
   573→
   574→	// 4. 오브젝트를 그리드에 매핑 (RoundToInt로 CalculateBrickGridIndex와 일치)
   575→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   576→	{
   577→		const FVector& Location = Entry.Transform.GetLocation();
   578→
   579→		// 월드 좌표 → 그리드 인덱스
   580→		int32 Col = FMath::RoundToInt((Location.X - GridOrigin.X) / BrickSize.X);
   581→		int32 Row = FMath::RoundToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   582→
   583→		// 범위 체크
   584→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   585→		{
   586→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   587→			Grid[Row][Col] = BrickTypeValue;
   588→		}
   589→	}
   590→
   591→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   592→	FString CSVContent;
   593→
   594→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   595→	// CalculateBrickPosition은 CenterOffset을 그리드 중심으로 사용하므로, 그리드 중심 좌표를 저장
   596→	FVector CenterOffset;
   597→	CenterOffset.X = GridOrigin.X + (GridColumns - 1) * 0.5f * BrickSize.X;
   598→	CenterOffset.Y = GridOrigin.Y + (GridRows - 1) * 0.5f * BrickSize.Y;
   599→	CenterOffset.Z = 0.0f;
   600→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   601→		CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   602→
   603→	for (int32 Row = 0; Row < GridRows; ++Row)
   604→	{
   605→		for (int32 Col = 0; Col < GridColumns; ++Col)
   606→		{
   607→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   608→			if (Col < GridColumns - 1)
   609→			{
   610→				CSVContent += TEXT(",");
   611→			}
   612→		}
   613→		CSVContent += TEXT("\n");
   614→	}
   615→
   616→	// 6. 파일 저장
   617→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   618→
   619→	// 디렉토리 생성
   620→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   621→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   622→	{
   623→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   624→	}
   625→
   626→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   627→
   628→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   629→	{
   630→		LastExportedCSVPath = FilePath;
   631→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportLayoutAsCSV: Exported to '%s' (Grid: %dx%d)"),
   632→			*FilePath, GridColumns, GridRows);
   633→		return true;
   634→	}
   635→	else
   636→	{
   637→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: Failed to save file '%s'"), *FilePath);
   638→		return false;
   639→	}
   640→}
