   128→bool UJumpMapLayoutDataAsset::ParseLayoutCSV(const FString& FileContent, FJumpMapLayout& OutLayout) const
   129→{
   130→	TArray<FString> Lines;
   131→	FileContent.ParseIntoArrayLines(Lines);
   132→
   133→	bool bHeaderParsed = false;
   134→
   135→	for (const FString& Line : Lines)
   136→	{
   137→		if (Line.IsEmpty()) continue;
   138→
   139→		// 메타데이터 라인 (#META:Key:Value)
   140→		if (Line.StartsWith(TEXT("#")))
   141→		{
   142→			if (Line.StartsWith(TEXT("#META:MapName:")))
   143→			{
   144→				OutLayout.LayoutName = Line.RightChop(14); // "#META:MapName:" 길이 = 14
   145→				OutLayout.LayoutName.TrimStartAndEndInline();
   146→			}
   147→			continue;
   148→		}
   149→
   150→		// CSV 헤더 행 건너뛰기
   151→		if (!bHeaderParsed && Line.Contains(TEXT("ObjectId")))
   152→		{
   153→			bHeaderParsed = true;
   154→			continue;
   155→		}
   156→
   157→		// 데이터 행 파싱: ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ
   158→		TArray<FString> Values;
   159→		Line.ParseIntoArray(Values, TEXT(","), true);
   160→
   161→		if (Values.Num() < 10)
   162→		{
   163→			UE_LOG(LogWjWorld, Warning, TEXT("ParseLayoutCSV: Skipping line with insufficient columns (%d): %s"),
   164→				Values.Num(), *Line);
   165→			continue;
   166→		}
   167→
   168→		FJumpMapLayoutEntry Entry;
   169→		Entry.ObjectId = FName(*Values[0].TrimStartAndEnd());
   170→
   171→		FVector Location;
   172→		Location.X = FCString::Atof(*Values[1]);
   173→		Location.Y = FCString::Atof(*Values[2]);
   174→		Location.Z = FCString::Atof(*Values[3]);
   175→
   176→		FRotator Rotation;
   177→		Rotation.Pitch = FCString::Atof(*Values[4]);
   178→		Rotation.Yaw = FCString::Atof(*Values[5]);
   179→		Rotation.Roll = FCString::Atof(*Values[6]);
   180→
   181→		FVector Scale;
   182→		Scale.X = FCString::Atof(*Values[7]);
   183→		Scale.Y = FCString::Atof(*Values[8]);
   184→		Scale.Z = FCString::Atof(*Values[9]);
   185→
   186→		Entry.Transform = FTransform(Rotation, Location, Scale);
   187→
   188→		// 11번째 컬럼: 커스텀 프로퍼티 (하위 호환: 10컬럼도 정상 처리)
   189→		if (Values.Num() >= 11)
   190→		{
   191→			FString PropertiesStr = Values[10].TrimStartAndEnd();
   192→			if (!PropertiesStr.IsEmpty())
   193→			{
   194→				TArray<FString> PropertyPairs;
   195→				PropertiesStr.ParseIntoArray(PropertyPairs, TEXT("|"), true);
   196→
   197→				for (const FString& Pair : PropertyPairs)
   198→				{
   199→					FString Key, Value;
   200→					if (Pair.Split(TEXT("="), &Key, &Value))
   201→					{
   202→						Entry.CustomProperties.Add(Key.TrimStartAndEnd(), Value.TrimStartAndEnd());
   203→					}
   204→				}
   205→			}
   206→		}
   207→
   208→		OutLayout.Objects.Add(Entry);
   209→	}
   210→
   211→	UE_LOG(LogWjWorld, Log, TEXT("ParseLayoutCSV: Parsed %d objects for layout '%s'"),
   212→		OutLayout.Objects.Num(), *OutLayout.LayoutName);
   213→	return OutLayout.Objects.Num() > 0;
   214→}
   215→
   216→FString UJumpMapLayoutDataAsset::ExportLayoutToCSV(const FJumpMapLayout& Layout)
   217→{
   218→	FString Result;
   219→
   220→	// 메타데이터 헤더
   221→	Result += FString::Printf(TEXT("#META:MapName:%s\n"), *Layout.LayoutName);
   222→
   223→	// CSV 헤더
   224→	Result += TEXT("ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ,Properties\n");
   225→
   226→	// 데이터 행
   227→	for (const FJumpMapLayoutEntry& Entry : Layout.Objects)
   228→	{
   229→		const FVector Location = Entry.Transform.GetLocation();
   230→		const FRotator Rotation = Entry.Transform.Rotator();
   231→		const FVector Scale = Entry.Transform.GetScale3D();
   232→
   233→		// 커스텀 프로퍼티 직렬화 (Key=Value|Key=Value)
   234→		FString PropertiesStr;
   235→		for (const auto& Pair : Entry.CustomProperties)
   236→		{
   237→			if (!PropertiesStr.IsEmpty())
   238→			{
   239→				PropertiesStr += TEXT("|");
   240→			}
   241→			PropertiesStr += FString::Printf(TEXT("%s=%s"), *Pair.Key, *Pair.Value);
   242→		}
   243→
   244→		Result += FString::Printf(TEXT("%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%s\n"),
   245→			*Entry.ObjectId.ToString(),
   246→			Location.X, Location.Y, Location.Z,
   247→			Rotation.Pitch, Rotation.Yaw, Rotation.Roll,
   248→			Scale.X, Scale.Y, Scale.Z,
   249→			*PropertiesStr);
   250→	}
   251→
   252→	return Result;
   253→}
