   216→FString UJumpMapLayoutDataAsset::ExportLayoutToCSV(const FJumpMapLayout& Layout)
   217→{
   218→	FString Result;
   219→
   220→	// 메타데이터 헤더
   221→	Result += FString::Printf(TEXT("#META:MapName:%s\n"), *Layout.LayoutName);
   222→
   223→	// CSV 헤더
   224→	Result += TEXT("ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ,Properties\n");
   225→
   226→	// 데이터 행
   227→	for (const FJumpMapLayoutEntry& Entry : Layout.Objects)
   228→	{
   229→		const FVector Location = Entry.Transform.GetLocation();
   230→		const FRotator Rotation = Entry.Transform.Rotator();
   231→		const FVector Scale = Entry.Transform.GetScale3D();
   232→
   233→		// 커스텀 프로퍼티 직렬화 (Key=Value|Key=Value)
   234→		FString PropertiesStr;
   235→		for (const auto& Pair : Entry.CustomProperties)
   236→		{
   237→			if (!PropertiesStr.IsEmpty())
   238→			{
   239→				PropertiesStr += TEXT("|");
   240→			}
   241→			PropertiesStr += FString::Printf(TEXT("%s=%s"), *Pair.Key, *Pair.Value);
   242→		}
   243→
   244→		Result += FString::Printf(TEXT("%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%s\n"),
   245→			*Entry.ObjectId.ToString(),
   246→			Location.X, Location.Y, Location.Z,
   247→			Rotation.Pitch, Rotation.Yaw, Rotation.Roll,
   248→			Scale.X, Scale.Y, Scale.Z,
   249→			*PropertiesStr);
   250→	}
   251→
   252→	return Result;
   253→}
