   437→TArray<FString> UWjWorldPlacementComponent::GetSavedLayoutSlots() const
   438→{
   439→	TArray<FString> SlotNames;
   440→
   441→	// SaveGame 디렉토리에서 모든 .sav 파일 검색
   442→	FString SaveDirectory = FPaths::ProjectSavedDir() / TEXT("SaveGames");
   443→
   444→	IFileManager& FileManager = IFileManager::Get();
   445→	TArray<FString> FoundFiles;
   446→	FileManager.FindFiles(FoundFiles, *SaveDirectory, TEXT("*.sav"));
   447→
   448→	for (const FString& FileName : FoundFiles)
   449→	{
   450→		// .sav 확장자 제거하여 슬롯 이름 추출
   451→		FString SlotName = FPaths::GetBaseFilename(FileName);
   452→
   453→		// SaveGame을 로드하여 컨텍스트 확인
   454→		UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   455→			UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   456→		);
   457→
   458→		if (SaveGame && SaveGame->SavedContext == CurrentContext)
   459→		{
   460→			SlotNames.Add(SlotName);
   461→		}
   462→	}
   463→
   464→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Found %d saved layout slots for context '%s'"),
   465→		SlotNames.Num(), *GetPlacementContextName(CurrentContext));
   466→	return SlotNames;
   467→}
