   469→bool UWjWorldPlacementComponent::DeleteLayoutSlot(const FString& SlotName)
   470→{
   471→	// SaveGame 삭제
   472→	if (!UGameplayStatics::DeleteGameInSlot(SlotName, 0))
   473→	{
   474→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to delete save slot '%s'"), *SlotName);
   475→		return false;
   476→	}
   477→
   478→	// AW 컨텍스트: CSV 파일도 삭제
   479→	if (CurrentContext == EPlacementContext::ApproachingWall)
   480→	{
   481→		FString CSVPath = GetUserWallLayoutDirectory() / SlotName + TEXT(".csv");
   482→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   483→		if (PlatformFile.FileExists(*CSVPath))
   484→		{
   485→			PlatformFile.DeleteFile(*CSVPath);
   486→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   487→		}
   488→	}
   489→	// JumpMap 컨텍스트: CSV 파일도 삭제
   490→	else if (CurrentContext == EPlacementContext::JumpMap)
   491→	{
   492→		FString CSVPath = GetUserJumpMapLayoutDirectory() / SlotName + TEXT(".csv");
   493→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   494→		if (PlatformFile.FileExists(*CSVPath))
   495→		{
   496→			PlatformFile.DeleteFile(*CSVPath);
   497→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   498→		}
   499→	}
   500→
   501→	// 현재 로드된 슬롯이면 초기화
   502→	if (LoadedSlotName == SlotName)
   503→	{
   504→		LoadedSlotName.Empty();
   505→	}
   506→
   507→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted layout slot '%s'"), *SlotName);
   508→	return true;
   509→}
