    10→
    11→AWjWorldGameStateJumpMapEditor::AWjWorldGameStateJumpMapEditor()
    12→{
    13→	// 싱글플레이어 전용이므로 리플리케이션 불필요
    14→	bReplicates = false;
    15→}
    16→
    17→void AWjWorldGameStateJumpMapEditor::BeginPlay()
    18→{
    19→	Super::BeginPlay();
    20→
    21→	// 카탈로그 로드 후 SaveGame 로드
    22→	EnsureCatalogLoaded();
    23→	LoadLayoutFromSaveGame();
    24→}
    25→
    26→void AWjWorldGameStateJumpMapEditor::AddPlacedObject(const FPlacedObjectSaveEntry& Entry)
    27→{
    28→	PlacedObjects.Add(Entry);
    29→	RespawnAllPlacedObjects();
    30→	OnPlacementDataChanged.Broadcast();
    31→
    32→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateJumpMapEditor: Added object %s (Total: %d)"),
    33→		*Entry.ObjectId.ToString(), PlacedObjects.Num());
    34→}
    35→
    36→void AWjWorldGameStateJumpMapEditor::RemovePlacedObjectAt(int32 Index)
    37→{
    38→	if (PlacedObjects.IsValidIndex(Index))
    39→	{
    40→		FName RemovedId = PlacedObjects[Index].ObjectId;
    41→		PlacedObjects.RemoveAt(Index);
    42→		RespawnAllPlacedObjects();
    43→		OnPlacementDataChanged.Broadcast();
    44→
    45→		UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateJumpMapEditor: Removed object %s at index %d (Total: %d)"),
    46→			*RemovedId.ToString(), Index, PlacedObjects.Num());
    47→	}
    48→}
    49→
    50→void AWjWorldGameStateJumpMapEditor::SetPlacedObjects(const TArray<FPlacedObjectSaveEntry>& InPlacedObjects)
    51→{
    52→	PlacedObjects = InPlacedObjects;
    53→	RespawnAllPlacedObjects();
    54→	OnPlacementDataChanged.Broadcast();
    55→
    56→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateJumpMapEditor: Set %d placed objects"), PlacedObjects.Num());
    57→}
    58→
    59→void AWjWorldGameStateJumpMapEditor::ClearPlacedObjects()
    60→{
    61→	PlacedObjects.Empty();
    62→	RespawnAllPlacedObjects();
    63→	OnPlacementDataChanged.Broadcast();
    64→
    65→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateJumpMapEditor: Cleared all placed objects"));
    66→}
    67→
    68→void AWjWorldGameStateJumpMapEditor::RespawnAllPlacedObjects()
    69→{
    70→	UWorld* World = GetWorld();
    71→	if (!World)
    72→	{
    73→		return;
    74→	}
    75→
    76→	// 기존 스폰된 오브젝트 제거
    77→	for (AWjWorldPlacedObjectActor* Actor : SpawnedActors)
    78→	{
    79→		if (Actor && !Actor->IsPendingKillPending())
    80→		{
    81→			Actor->Destroy();
    82→		}
    83→	}
    84→	SpawnedActors.Empty();
    85→
    86→	// 카탈로그 폴백 로드 시도
    87→	EnsureCatalogLoaded();
    88→
    89→	// 카탈로그 없으면 스폰 불가
    90→	if (!Catalog)
    91→	{
    92→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateJumpMapEditor: Cannot respawn objects - no catalog set"));
    93→		return;
    94→	}
    95→
    96→	// 새로 스폰
    97→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
    98→	{
    99→		const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(Entry.ObjectId);
   100→		if (!Def)
   101→		{
   102→			UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateJumpMapEditor: ObjectId %s not found in catalog"),
   103→				*Entry.ObjectId.ToString());
   104→			continue;
   105→		}
   106→
   107→		FActorSpawnParameters SpawnParams;
   108→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   109→
   110→		AWjWorldPlacedObjectActor* NewActor = World->SpawnActor<AWjWorldPlacedObjectActor>(
   111→			AWjWorldPlacedObjectActor::StaticClass(),
   112→			Entry.Transform.GetLocation(),
   113→			Entry.Transform.GetRotation().Rotator(),
   114→			SpawnParams
   115→		);
   116→
   117→		if (NewActor)
   118→		{
   119→			NewActor->InitializeFromSaveData(Entry.ObjectId, Entry.Transform, *Def);
   120→			SpawnedActors.Add(NewActor);
   121→		}
   122→	}
   123→
   124→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateJumpMapEditor: Respawned %d objects"), SpawnedActors.Num());
   125→}
   126→
   127→void AWjWorldGameStateJumpMapEditor::EnsureCatalogLoaded()
   128→{
   129→	if (Catalog)
   130→	{
   131→		return;
   132→	}
   133→
   134→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   135→	if (!Settings)
   136→	{
   137→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateJumpMapEditor: DeveloperSettings not found"));
   138→		return;
   139→	}
   140→
   141→	// JumpMap 컨텍스트 카탈로그 로드
   142→	Catalog = Settings->GetPlaceableCatalogForContext(EPlacementContext::JumpMap);
   143→	if (Catalog)
   144→	{
   145→		UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateJumpMapEditor: Catalog loaded for JumpMap context"));
   146→	}
   147→	else
   148→	{
   149→		UE_LOG(LogWjWorldPlacement, Error, TEXT("GameStateJumpMapEditor: Failed to load PlaceableObjectCatalog"));
   150→	}
   151→}
   152→
   153→void AWjWorldGameStateJumpMapEditor::LoadLayoutFromSaveGame()
   154→{
   155→	FString SlotName = GetSaveSlotNameForContext(EPlacementContext::JumpMap);
   156→
   157→	if (!UGameplayStatics::DoesSaveGameExist(SlotName, 0))
   158→	{
   159→		UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateJumpMapEditor: No save game found at slot '%s'"), *SlotName);
   160→		return;
   161→	}
   162→
   163→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   164→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   165→	);
   166→
   167→	if (!SaveGame)
   168→	{
   169→		UE_LOG(LogWjWorldPlacement, Error, TEXT("GameStateJumpMapEditor: Failed to load save game from slot '%s'"), *SlotName);
   170→		return;
   171→	}
   172→
   173→	SetPlacedObjects(SaveGame->PlacedObjects);
   174→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateJumpMapEditor: Loaded %d objects from slot '%s'"),
   175→		SaveGame->PlacedObjects.Num(), *SlotName);
   176→}
