void UWjWorldGameRuleJumpMap::LoadLayoutAndSpawnActors()
{
    UWorld* World = GetWorld();
    if (!World) return;

    const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
    if (!DevSettings) return;

    // MapOption에서 레이아웃 이름 가져오기
