    bool bLoadedFromCSV = false;
    if (!MapOpt.IsEmpty() && !MapOpt.Equals(TEXT("Default"), ESearchCase::IgnoreCase)
        && !MapOpt.Equals(TEXT("Random"), ESearchCase::IgnoreCase))
    {
        if (!DevSettings->JumpMapLayoutDataAsset.IsNull())
